import sys, pathlib, tempfile, subprocess, ctypes as C, json, math
import numpy as np
R=pathlib.Path.cwd();sys.path.insert(0,str(R))
from experiments.bank_memory_001.test_memory import Tests
from experiments.sram_size_001.native import Native,CardinalMap,projected_coefficients
from experiments.bank_rowwise_001.native import ptr
out={}
with tempfile.TemporaryDirectory(prefix='sram-review-') as temp:
 p=pathlib.Path(temp);Tests.setUpClass()
 try:
  t=Tests();fields=[t.make(3) for _ in range(3)]
  ns=[Native(fields[i],t.mean,t.L,p/str(i),math_kind=k,map_kind='cardinal',compact=True) for i,k in enumerate(['libm','tiny'])]
  for n in ns:n.initialize(np.zeros(16))
  # Public fixture, repeated with changing signs and actual irregular dt.
  obs=np.tile(t.obs,(20,1));obs[:,0]=np.tile([0.,1e-10,.01,1/35,.2],len(obs)//5+1)[:len(obs)];obs[:,1]=np.tile([0.,.05,-.05,.2,-.2],len(obs)//5+1)[:len(obs)]
  for first in range(0,len(obs),127):fields[2].update(first,obs[first:first+127])
  for first in range(0,len(obs),127):
   for n in ns:n.advance(first,obs[first:first+127])
  idx=np.r_[18:24,27:33,36:39]
  out['stream']={}
  for label,f in zip(['libm','tiny'],fields):
   out['stream'][label]={'n':len(obs),'state_max_abs_vs_original':float(abs(f.state[idx]-fields[2].state[idx]).max()),'rc_free_max_abs':float(abs(f.rc_free-fields[2].rc_free).max()),'rc_forced_max_abs':float(abs(f.rc_forced-fields[2].rc_forced).max()),'history_max_abs':float(abs(f.packed.values-fields[2].packed.values).max()),'history_gram_max_abs':float(abs(f.root.T@f.root-fields[2].root.T@fields[2].root).max()),'history_gram_relative_max':float(abs(f.root.T@f.root-fields[2].root.T@fields[2].root).max()/abs(fields[2].root.T@fields[2].root).max())}
  # Fractional and node-adjacent projected value/derivative controls.
  f=fields[0];cm=CardinalMap(f.map);u=np.r_[np.linspace(-1,1,4001),np.arange(-4,5)/4,np.nextafter(np.arange(-4,5)/4,np.inf),np.nextafter(np.arange(-4,5)/4,-np.inf)];u=u[abs(u)<=1]
  a=projected_coefficients(f);out['projection']={'value_max_abs':float(abs(np.polynomial.chebyshev.chebval(u,a.T).T-cm.weights(u)@f.P.T).max()),'derivative_max_abs':float(abs(np.polynomial.chebyshev.chebval(u,np.polynomial.chebyshev.chebder(a.T)).T-cm.weights(u,1)@f.P.T).max())}
  # Partial failure and explicit inference quarantine. Failure after successful first row.
  n=ns[0];first=n.field.count;before=n.field.packed.values.copy();bad=obs[:2].copy();bad[1,2]=26
  try:n.advance(first,bad)
  except ValueError:pass
  out['partial_failure']={'count_unchanged':n.field.count==first,'history_mutated':not np.array_equal(before,n.field.packed.values),'valid_flag':n.context.qr.lease.valid}
  try:n.query();out['partial_failure']['query_refused']=False
  except ValueError:out['partial_failure']['query_refused']=True
  n.initialize(np.zeros(16));out['partial_failure']['initialize_can_reenable_partial_state']=bool(n.context.qr.lease.valid)
 finally:Tests.tearDownClass()
 # Helpers and cumulative QR compile tiny and libm identical loops.
 for kind in ['tiny','libm']:
  src=p/(kind+'.c');src.write_text(('#include "'+str(R/'experiments/sram_size_001/tiny_math.h')+'"\n' if kind=='tiny' else '#include <math.h>\n')+'#define STORE_DOUBLE 1\n#include "'+str(R/'experiments/bank_memory_001/qr.c')+'"\ndouble test(unsigned op,double x,double y){switch(op){case 0:return exp(x);case 1:return log(x);case 2:return sqrt(x);case 3:return hypot(x,y);case 4:return tanh(x);case 5:return atanh(x);default:return expm1(x);}}\nint repeated(double*r,unsigned n){for(unsigned i=0;i<n;i++){double row[4]={1.,1.+(i%3)*1e-8,(i%2?1.:-1.)*1e-6,.5};if(insert(r,4,row))return -1;}return 0;}\n')
  so=p/(kind+'.so');subprocess.run(['cc','-Os','-fPIC','-shared','-ffp-contract=off',str(src),'-lm','-o',str(so)],check=True);lib=C.CDLL(str(so));lib.test.argtypes=[C.c_uint,C.c_double,C.c_double];lib.test.restype=C.c_double;lib.repeated.argtypes=[C.POINTER(C.c_double),C.c_uint]
  if kind=='tiny':tiny=lib
  else:exact=lib
 out['helper_edges']=[]
 for op in range(7):
  for x in [-math.inf,-1.,-0.,0.,5e-324,1.,math.inf,math.nan]:
   a=tiny.test(op,x,0);b=exact.test(op,x,0)
   same=(math.isnan(a) and math.isnan(b)) or a==b
   if not same or (a==b==0 and math.copysign(1,a)!=math.copysign(1,b)):out['helper_edges'].append({'op':op,'x':str(x),'tiny':str(a),'libm':str(b)})
 out['qr_prefixes']=[]
 for n in [100,10000,100000]:
  rs=[]
  for lib in [tiny,exact]:
   a=np.zeros(10);assert lib.repeated(ptr(a),n)==0;r=np.zeros((4,4));r[np.triu_indices(4)]=a;rs.append(r)
  out['qr_prefixes'].append({'n':n,'factor_max_abs':float(abs(rs[0]-rs[1]).max()),'gram_max_abs':float(abs(rs[0].T@rs[0]-rs[1].T@rs[1]).max())})
 print(json.dumps(out,indent=2))
 pathlib.Path('/tmp/sram_core_review_r1_results.json').write_text(json.dumps(out,indent=2))
